x solid #62d9ee}.menu-row.drop-after>.menu-card{border-bottom:2px solid #62d9ee}.menu-row.drop-inside>.menu-card{border-color:rgba(98,217,238,.75);box-shadow:0 0 0 2px rgba(98,217,238,.09)}.menu-card-top{display:flex;align-items:center;justify-content:space-between;gap:10px}.menu-card-title{display:flex;align-items:center;gap:8px;min-width:0}.drag-handle{color:#5d8290;padding:4px;cursor:grab}.type-icon{width:29px;height:29px;display:grid;place-items:center;border-radius:8px;background:rgba(98,217,238,.08);color:#62d9ee;flex:0 0 auto}.type-icon.folder{color:#8dc9ff;background:rgba(141,201,255,.08)}.menu-card-name{font-size:11px;font-weight:800;color:#e5f7fa;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.item-actions{display:flex;gap:4px;flex:0 0 auto}.move-btn,.rename-btn{width:28px;height:28px;border:1px solid var(--line);border-radius:7px;background:rgba(255,255,255,.025);color:#82a6b1;cursor:pointer}.menu-card-meta{display:flex;gap:6px;flex-wrap:wrap;margin:8px 0 5px 72px;color:#6f909d;font-size:8px}.type-pill{padding:3px 6px;border-radius:999px;color:#79d8e9;border:1px solid rgba(98,217,238,.18);background:rgba(98,217,238,.05)}.menu-card-url{display:block;color:#5f808c;font-size:8px;padding-left:72px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.nest-hint{margin:9px 0 0 72px;padding:7px 9px;border:1px dashed rgba(98,217,238,.14);border-radius:8px;color:#668895;font-size:8px}.nest-hint i{color:#62d9ee;margin-right:5px}.menu-children{display:grid;gap:7px;margin:7px 0 0 24px;padding-left:12px;border-left:1px solid rgba(98,217,238,.12)}.empty-drop-zone{min-height:30px;display:grid;place-items:center;padding:8px;border:1px dashed rgba(98,217,238,.18);border-radius:9px;color:#5f808c;font-size:8px}.empty-drop-zone.drop-active,.root-drop-zone.drop-active{border-color:#62d9ee;color:#b5edf4;background:rgba(98,217,238,.045)}.root-drop-zone{display:flex;align-items:center;justify-content:center;gap:7px;min-height:32px;margin-top:9px;border:1px dashed rgba(98,217,238,.12);border-radius:9px;color:#5e7e8a;font-size:8px}.add-mode{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:5px;padding:4px;background:rgba(255,255,255,.025);border-radius:10px;margin-bottom:12px}.add-mode-btn{border:0;background:transparent;color:#76939e;border-radius:8px;padding:9px 5px;font-size:9px;font-weight:700;cursor:pointer}.add-mode-btn.active{background:rgba(98,217,238,.1);color:#e7fbff}.builder-form,.edit-grid,.edit-box{display:grid;gap:9px}.builder-form label,.edit-box label{font-size:9px;color:#88a6b1}.builder-form input,.builder-form select,.edit-box input,.edit-box select{width:100%;box-sizing:border-box;margin-top:5px;padding:9px;border-radius:9px;border:1px solid var(--line);background:#071b27;color:#e8f6fa;font-size:10px}.primary,.danger{border:0;border-radius:9px;padding:10px 12px;background:#31afd2;color:#fff;font-weight:700;cursor:pointer;font-size:10px}.primary:disabled{opacity:.4;cursor:not-allowed}.danger{background:transparent;border:1px solid rgba(255,100,100,.25);color:#ff9a9a}.check{display:flex!important;align-items:center;gap:7px}.check input{width:auto!important;margin:0!important}.source-preview,.locked-source{display:flex;gap:8px;align-items:center;padding:9px;border:1px solid var(--line);border-radius:9px;background:rgba(255,255,255,.018);color:#7899a5;font-size:8px}.locked-source span{flex:1}.locked-source small{display:block;color:#718f9a;margin-top:2px}.locked-source b{font-size:7px;color:#62d9ee}.is-hidden{display:none!important}.edit-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.edit-card{border:1px solid var(--line);border-radius:12px;background:rgba(255,255,255,.018);overflow:hidden}.edit-card summary{list-style:none;display:flex;align-items:center;justify-content:space-between;gap:9px;padding:12px;cursor:pointer;color:#dff7fb}.edit-card summary::-webkit-details-marker{display:none}.edit-card[open] summary{border-bottom:1px solid var(--line);background:rgba(98,217,238,.025)}.edit-card-title{display:flex;align-items:center;gap:8px;min-width:0}.edit-card-title strong{display:block;font-size:10px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.edit-card-title small{display:block;color:#6f909d;font-size:8px;margin-top:3px}.mini-icon{width:25px;height:25px;display:grid;place-items:center;border-radius:7px;color:#62d9ee;background:rgba(98,217,238,.08)}.edit-content{padding:12px}.empty{display:grid;place-items:center;gap:5px;min-height:130px;border:1px dashed var(--line);border-radius:12px;color:#6d8c98;text-align:center;font-size:9px}.empty i{font-size:20px;color:#62d9ee}.empty strong{color:#bcd7df;font-size:10px}@media(max-width:1050px){.builder-grid{grid-template-columns:1fr}.edit-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:700px){.builder-card{padding:13px}.builder-toolbar{align-items:flex-start;flex-direction:column}.desktop-tip{display:none}.edit-grid{grid-template-columns:1fr}.menu-card-meta,.menu-card-url{margin-left:0;padding-left:0}.nest-hint{margin-left:0}.item-actions .move-btn{display:none}.mode-tabs a{flex:1}}
