@push('scripts')<script>
(function(){const tree=document.getElementById('menu-tree');if(!tree)return;const reorderUrl=@json(route('admin.menu-builder.reorder')),csrf=@json(csrf_token()),menu=@json($menu),state=document.getElementById('save-state'),root=document.getElementById('root-drop-zone');let dragged=null,timer=null;
function stateSet(type,text){state.className='save-indicator '+type;state.innerHTML='<i class="fa-solid '+(type==='saving'?'fa-spinner fa-spin':type==='error'?'fa-triangle-exclamation':'fa-circle-check')+'"></i><span>'+text+'</span>'}function rows(c){return Array.from(c.children).filter(x=>x.classList.contains('menu-row'))}function childBox(r){let c=Array.from(r.children).find(x=>x.classList.contains('menu-children'));if(!c){c=document.createElement('div');c.className='menu-children';c.dataset.parentId=r.dataset.id;r.appendChild(c)}return c}function descendant(r,id){return !!r.querySelector('.menu-row[data-id="'+CSS.escape(String(id))+'"]')}function clear(){document.querySelectorAll('.drop-before,.drop-after,.drop-inside,.drop-active').forEach(x=>x.classList.remove('drop-before','drop-after','drop-inside','drop-active'))}
function save(){clearTimeout(timer);timer=setTimeout(async()=>{const payload=[];function walk(c,parent){rows(c).forEach((r,i)=>{payload.push({id:Number(r.dataset.id),parent_id:parent===null?null:Number(parent),sort_order:i});const cc=Array.from(r.children).find(x=>x.classList.contains('menu-children'));if(cc)walk(cc,Number(r.dataset.id))})}walk(tree,null);stateSet('saving','Saving changes…');try{const res=await fetch(reorderUrl,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':csrf,'X-Requested-With':'XMLHttpRequest'},body:JSON.stringify({menu,tree:payload})});const data=await res.json().catch(()=>({}));if(!res.ok||data.ok!==true)throw new Error(data.message||'The menu could not be saved.');stateSet('','All changes saved')}catch(e){stateSet('error',e.message||'Save failed')}},80)}
function bind(){document.querySelectorAll('.menu-row[draggable="true"]').forEach(r=>{r.addEventListener('dragstart',e=>{dragged=r;r.classList.add('dragging');e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',r.dataset.id)});r.addEventListener('dragend',()=>{r.classList.remove('dragging');dragged=null;clear()});r.addEventListener('dragover',e=>{if(!dragged||dragged===r||descendant(dragged,r.dataset.id))return;e.preventDefault();clear();if(r.dataset.kind==='folder'&&e.altKey)r.classList.add('drop-inside');else if(e.clientY<r.getBoundingClientRect().top+r.getBoundingClientRect().height/2)r.classList.add('drop-before');else r.classList.add('drop-after')});r.addEventListener('drop',e=>{if(!dragged||dragged===r||descendant(dragged,r.dataset.id))return;e.preventDefault();if(r.dataset.kind==='folder'&&e.altKey)childBox(r).appendChild(dragged);else if(e.clientY<r.getBoundingClientRect().top+r.getBoundingClientRect().height/2)r.parentElement.insertBefore(dragged,r);else r.parentElement.insertBefore(dragged,r.nextSibling);clear();save()})});document.querySelectorAll('.menu-children').forEach(c=>{c.addEventListener('dragover',e=>{if(!dragged)return;e.preventDefault();c.classList.add('drop-active')});c.addEventListener('dragleave',()=>c.classList.remove('drop-active'));c.addEventListener('drop',e=>{if(!dragged||c.closest('.menu-row')===dragged)return;e.preventDefault();c.appendChild(dragged);c.classList.remove('drop-active');clear();save()})})}
root.addEventListener('dragover',e=>{if(!dragged)return;e.preventDefault();root.classList.add('drop-active')});root.addEventListener('dragleave',()=>root.classList.remove('drop-active'));root.addEventListener('drop',e=>{if(!dragged)return;e.preventDefault();tree.appendChild(dragged);root.classList.remove('drop-active');clear();save()});document.querySelectorAll('.move-up,.move-down').forEach(b=>b.addEventListener('click',()=>{const r=document.querySelector('.menu-row[data-id="'+CSS.escape(b.dataset.id)+'"]');if(!r)return;const prev=r.previousElementSibling,next=r.nextElementSibling;if(b.classList.contains('move-up')&&prev?.classList.contains('menu-row'))r.parentElement.insertBefore(r,prev);if(b.classList.contains('move-down')&&next?.classList.contains('menu-row'))r.parentElement.insertBefore(r,next.nextSibling);save()}));
const buttons=document.querySelectorAll('.add-mode-btn'),kind=document.getElementById('kind'),select=document.getElementById('source-select'),key=document.getElementById('source-key'),sf=document.getElementById('source-fields'),uf=document.getElementById('url-fields'),ff=document.getElementById('folder-fields'),add=document.getElementById('add-button'),ul=document.getElementById('url-label'),uv=document.getElementById('url-value'),fl=document.getElementById('folder-label'),sp=document.getElementById('source-preview'),up=document.getElementById('url-preview');function valid(){let ok=kind.value==='source'?!!select.value:kind.value==='url'?!!ul.value.trim()&&!!uv.value.trim():!!fl.value.trim();add.disabled=!ok}function mode(m){kind.value=m;buttons.forEach(b=>b.classList.toggle('active',b.dataset.mode===m));sf.classList.toggle('is-hidden',m!=='source');uf.classList.toggle('is-hidden',m!=='url');ff.classList.toggle('is-hidden',m!=='folder');select.required=m==='source';ul.required=m==='url';uv.required=m==='url';fl.required=m==='folder';valid()}buttons.forEach(b=>b.addEventListener('click',()=>mode(b.dataset.mode)));select.addEventListener('change',()=>{key.value=select.value;const o=select.selectedOptions[0];sp.innerHTML=o?.value?'<strong>'+o.dataset.label+'</strong><span>'+o.dataset.url+'</span>':'Select a destination to continue.';valid()});[ul,uv,fl].forEach(x=>x.addEventListener('input',()=>{if(x===uv)up.textContent=uv.value.trim()||'Enter a URL to preview it.';valid()}));bind();})();
</script>@endpush
